let orderStatusAudioContext=null;
let orderStatusAudioUnlocked=false;
function unlockOrderStatusAudio(){
 try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;orderStatusAudioContext=orderStatusAudioContext||new AudioCtx();if(orderStatusAudioContext.state==='suspended')orderStatusAudioContext.resume();orderStatusAudioUnlocked=true;}catch(error){console.warn('Status audio unavailable',error)}
}
window.addEventListener('pointerdown',unlockOrderStatusAudio,{passive:true});
window.addEventListener('keydown',unlockOrderStatusAudio);
function openAdminPhotoZoom(src,label){const overlay=document.createElement('div');overlay.className='admin-photo-zoom-overlay';overlay.innerHTML='<div class="admin-photo-zoom-toolbar"><strong></strong><button type="button" data-zoom-out aria-label="Փոքրացնել">−</button><button type="button" data-zoom-reset>100%</button><button type="button" data-zoom-in aria-label="Մեծացնել">＋</button><button type="button" data-zoom-close aria-label="Փակել">✕</button></div><div class="admin-photo-zoom-stage"><img alt=""></div>';overlay.querySelector('strong').textContent=label||'Լուսանկարի դիտում';const img=overlay.querySelector('img');img.src=src;img.alt=label||'Լուսանկար';let scale=1;const apply=()=>{img.style.transform='scale('+scale+')';overlay.querySelector('[data-zoom-reset]').textContent=Math.round(scale*100)+'%'};overlay.querySelector('[data-zoom-in]').onclick=()=>{scale=Math.min(4,scale+.25);apply()};overlay.querySelector('[data-zoom-out]').onclick=()=>{scale=Math.max(.5,scale-.25);apply()};overlay.querySelector('[data-zoom-reset]').onclick=()=>{scale=1;apply()};overlay.querySelector('[data-zoom-close]').onclick=()=>overlay.remove();overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});overlay.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.5,Math.min(4,scale+(e.deltaY<0?.15:-.15)));apply()},{passive:false});document.body.appendChild(overlay);}
function enableAdminPhotoZoom(root){if(!root||root.dataset.photoZoomBound)return;root.dataset.photoZoomBound='1';root.addEventListener('click',event=>{const img=event.target.closest('img');if(img&&root.contains(img)&&img.src)openAdminPhotoZoom(img.src,img.alt||img.closest('figure')?.querySelector('figcaption')?.textContent||'Լուսանկար')})}
function playOrderStatusTone(){
 try{
  const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;
  orderStatusAudioContext=orderStatusAudioContext||new AudioCtx();
  if(orderStatusAudioContext.state==='suspended'&&orderStatusAudioUnlocked)orderStatusAudioContext.resume();
  if(orderStatusAudioContext.state!=='running')return;
  const ctx=orderStatusAudioContext,now=ctx.currentTime;
  const notes=[660,784,988,784,880,1046];
  notes.forEach((frequency,index)=>{const start=now+index*.62,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.12,start+.045);gain.gain.exponentialRampToValueAtTime(.0001,start+.42);osc.connect(gain);gain.connect(ctx.destination);osc.start(start);osc.stop(start+.45)});
 }catch(error){console.warn('Status sound failed',error)}
}
function playUrgentSelectionTone(){
 try{
  const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;
  orderStatusAudioContext=orderStatusAudioContext||new AudioCtx();
  if(orderStatusAudioContext.state==='suspended'&&orderStatusAudioUnlocked)orderStatusAudioContext.resume();
  if(orderStatusAudioContext.state!=='running')return;
  const ctx=orderStatusAudioContext,now=ctx.currentTime;
  [784,988,1175].forEach((frequency,index)=>{
   const start=now+index*.105,osc=ctx.createOscillator(),gain=ctx.createGain();
   osc.type='triangle';osc.frequency.setValueAtTime(frequency,start);
   gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.055,start+.018);
   gain.gain.exponentialRampToValueAtTime(.0001,start+.19);
   osc.connect(gain);gain.connect(ctx.destination);osc.start(start);osc.stop(start+.2);
  });
 }catch(error){console.warn('Urgent selection sound unavailable',error)}
}
function announceOrderStatus(data){
 const labels={OPEN:'Նոր պատվեր',ACCEPTED:'Վարորդն ընդունել է պատվերը',ARRIVED:'Վարորդը տեղում է',IN_PROGRESS:'Ուղևորությունը սկսվել է',COMPLETED:'Պատվերն ավարտվել է',CANCELLED:'Պատվերը չեղարկվել է'};
 const label=labels[data?.status]||'Պատվերի կարգավիճակը փոխվել է';
 const detail=(data?.message||'')+(data?.orderCode?' · Պատվեր №'+String(data.orderCode).padStart(4,'0'):'');
 let toast=document.getElementById('orderStatusLiveToast');
 if(!toast){toast=document.createElement('aside');toast.id='orderStatusLiveToast';toast.className='order-status-live-toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','assertive');document.body.appendChild(toast)}
 toast.innerHTML='<strong></strong><span></span>';
 toast.querySelector('strong').textContent=label;toast.querySelector('span').textContent=detail;
 toast.classList.add('visible');clearTimeout(toast._hideTimer);toast._hideTimer=setTimeout(()=>toast.classList.remove('visible'),6500);
 playOrderStatusTone();
}

async function refreshAdminPhotoReviewNotifications(){const box=$('#adminPhotoReviewQueue');if(!box||currentUser?.role!=='ADMIN')return;try{const data=await api('/api/admin/drivers');const items=(data.drivers||[]).filter(x=>x.driverDocumentsStatus==='PENDING_REVIEW'||x.driverProfilePhotoStatus==='PENDING_REVIEW'||x.vehicleDocumentsStatus==='PENDING_REVIEW'||x.periodicVehicleVerificationStatus==='PENDING_REVIEW');const count=$('#adminPhotoReviewSection .photo-review-count'),pulse=$('#adminPhotoReviewSection .photo-review-pulse');if(count)count.textContent=items.length+' ՆՈՐ ՀԱՅՏ';if(pulse)pulse.hidden=!items.length;box.innerHTML=items.length?items.map(x=>'<article class="photo-review-queue-item"><div><strong>'+esc(x.name)+'</strong><p>'+esc(x.phone||'')+' · '+esc(x.email||'')+'</p><small>'+[x.driverDocumentsStatus==='PENDING_REVIEW'?'Անձնական փաստաթղթեր':null,x.driverProfilePhotoStatus==='PENDING_REVIEW'?'Պրոֆիլի լուսանկար':null,x.vehicleDocumentsStatus==='PENDING_REVIEW'?'Մեքենայի փաստաթղթեր':null,x.periodicVehicleVerificationStatus==='PENDING_REVIEW'?'72-ժամյա լուսանկարներ և սելֆի':null].filter(Boolean).join(' · ')+'</small></div><button type="button" class="action" data-unified-photo-profile="'+x.id+'">ԲԱՑԵԼ ԱՄԲՈՂՋԱԿԱՆ ՊՐՈՖԻԼԸ</button></article>').join(''):'<p class="empty-state">Նոր ֆոտոստուգման հայտեր չկան։</p>';if(openAdminUnifiedProfile)box.querySelectorAll('[data-unified-photo-profile]').forEach(button=>button.onclick=()=>openAdminUnifiedProfile(button));}catch(error){box.innerHTML='<p class="empty-state">Ֆոտոստուգումը բեռնել չհաջողվեց․ '+esc(error.message)+'</p>'}}
function connectRealtime(){
 if(!window.io||!token)return;
 if(realtimeSocket)realtimeSocket.disconnect();
 realtimeSocket=window.io({auth:{token},transports:['websocket','polling']});
 const refresh=()=>{
  // Never rebuild an active page because of a realtime event. This preserves
  // open menus, panels, completed-order views, photo viewers and touch state.
  // Dedicated order polling updates list contents without replacing the screen.
  return;
 };
 realtimeSocket.on('driver:balance-updated',data=>{if(currentUser?.role==='DRIVER'&&data?.driverId===currentUser.id&&Number.isFinite(Number(data.balanceAmd))){currentUser.balanceAmd=Number(data.balanceAmd);const amount=$('#driverBalanceAmount');if(amount)amount.textContent=money(currentUser.balanceAmd);}});
  realtimeSocket.on('order:status-changed',data=>{announceOrderStatus(data);refresh()});
  realtimeSocket.on('order:eta-updated',()=>refresh());
  realtimeSocket.on('order:new',data=>{if(currentUser?.role==='DRIVER')announceOrderStatus({...data,status:'OPEN',message:'Նոր պատվեր է հասանելի։'});refresh()});
  ['order:cancelled','order:accepted','order:fare-updated','order:completed','notification:new','site-content:updated'].forEach(eventName=>realtimeSocket.on(eventName,refresh));
  if(realtimeFallbackTimer)clearInterval(realtimeFallbackTimer);
  realtimeFallbackTimer=setInterval(()=>{if(!realtimeSocket?.connected)refresh()},5000);
  // Socket reconnects must not reset the user's current screen.

 realtimeSocket.on('notification:new',data=>{if(currentUser?.role==='ADMIN'&&['VEHICLE_PHOTO_REVIEW','PROFILE_PHOTO_REVIEW','PERIODIC_VEHICLE_REVIEW'].includes(data?.type))refreshAdminPhotoReviewNotifications()});
 realtimeSocket.on('rating:updated',()=>{if(currentUser?.role==='ADMIN'){if($('#adminCustomersPanel'))loadAdminCustomers();const ratingsTab=$('#dashboard [data-admin-tab="ratings"]');if(ratingsTab?.classList.contains('active'))ratingsTab.click();}});
 realtimeSocket.on('connect_error',error=>console.warn('STAP live connection:',error.message));
}

