function setMode(next){if(lockedAppRole==='ADMIN'&&next==='register')next='login';mode=next;setPublicAuthVisible(true);const registering=mode==='register';if(lockedAppRole){const roleField=$('#role');if(roleField)roleField.value=lockedAppRole;}$('#loginTab').classList.toggle('active',!registering);$('#registerTab').classList.toggle('active',registering);$('#registerFields').classList.toggle('hidden',!registering);['name','phone','role'].forEach(name=>{const field=$('#authForm [name='+name+']');field.disabled=!registering;field.required=registering&&name!=='role'});syncLicenseField();const submitAuth=$('#submitAuth');if(submitAuth)submitAuth.textContent=registering?'Գրանցվել':'Մուտք գործել';const identityField=$('#authForm [name=email]');if(identityField){identityField.type=registering?'email':'text';identityField.placeholder=registering?'name@example.com':'Հեռախոսահամար կամ name@example.com';identityField.autocomplete='username';const identityLabel=identityField.closest('label');if(identityLabel)identityLabel.firstChild.textContent=registering?'Էլ․ փոստ':'Հեռախոսահամար կամ էլ․ փոստ'}const passwordField=$('#authForm [name=password]');passwordField.autocomplete=registering?'new-password':'current-password';passwordField.minLength=registering?10:1;message('#authMessage','')}
$('#loginTab').addEventListener('click',()=>setMode('login'));
