async function api(path, options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(token)headers.Authorization='Bearer '+token;const res=await fetch(path,{...options,headers});const data=await res.json().catch(()=>({error:'Սերվերի պատասխանը հասկանալի չէ'}));if(!res.ok)throw new Error((data.error||'Հարցումը չհաջողվեց')+(data.requestId?' · Սխալի կոդ՝ '+data.requestId:''));return data}
authForm.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(authForm);const body={email:f.get('email'),password:f.get('password')};if(mode==='register'){body.name=f.get('name');body.phone=f.get('phone');body.role=lockedAppRole||'CUSTOMER';if(f.get('driverLicenseIssuedAt'))body.driverLicenseIssuedAt=f.get('driverLicenseIssuedAt');if(body.role==='DRIVER'){body.driverLicense=f.get('driverLicense');body.driverFirstNameLatin=f.get('driverFirstNameLatin');body.driverLastNameLatin=f.get('driverLastNameLatin');body.driverPatronymicLatin=f.get('driverPatronymicLatin');body.driverLicenseSeries=f.get('driverLicenseSeries');body.driverLicenseExpiresAt=f.get('driverLicenseExpiresAt');body.driverServiceCapabilities=f.getAll('driverServiceCapabilities')}}
try{message('#authMessage','Կատարվում է...');const data=await api(mode==='login'?'/api/auth/login':'/api/auth/register',{method:'POST',body:JSON.stringify(body)});if(lockedAppRole&&data.user.role!==lockedAppRole)throw new Error(lockedAppRole==='DRIVER'?'Այս հավելվածում մուտք գործելու համար անհրաժեշտ է վարորդի հաշիվ։':lockedAppRole==='ADMIN'?'Ադմինի մուտքի տվյալները սխալ են կամ հաշիվը ադմին չէ։':'Այս հավելվածում մուտք գործելու համար անհրաժեշտ է հաճախորդի հաշիվ։');token=data.token;localStorage.setItem('stap_token',token);currentUser=data.user;await showApp()}catch(err){const details=err.details?.map(x=>x.message).filter(Boolean).join('։ ');message('#authMessage',details?err.message+'։ '+details:err.message,true)}});
