let driverAlertAudioContext=null,driverAlertSoundTimer=null,driverAlertToastTimer=null;
function unlockDriverAlertAudio(){try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;if(!driverAlertAudioContext)driverAlertAudioContext=new AudioCtx();if(driverAlertAudioContext.state==='suspended')driverAlertAudioContext.resume()}catch(_){}}
document.addEventListener('pointerdown',unlockDriverAlertAudio,{passive:true});
document.addEventListener('keydown',unlockDriverAlertAudio);
function playSoftDriverOrderChime(){try{const ctx=driverAlertAudioContext;if(!ctx||ctx.state!=='running')return;const now=ctx.currentTime;[[740,0],[988,.16]].forEach(([frequency,delay])=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(frequency,now+delay);gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(.026,now+delay+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+.24);osc.connect(gain);gain.connect(ctx.destination);osc.start(now+delay);osc.stop(now+delay+.26)})}catch(_){}}
function notifyDriverOfNewOrders(orders){if(!orders.length)return;const toast=document.getElementById('driverNewOrderAlert')||document.body.appendChild(Object.assign(document.createElement('div'),{id:'driverNewOrderAlert'}));toast.className='driver-new-order-alert';toast.innerHTML='<strong>ՆՈՐ ՊԱՏՎԵՐ</strong><span>'+(orders.length===1?'Ձեզ հասանելի է նոր պատվեր։':orders.length+' նոր պատվեր հասանելի է։')+'</span><small>Բացեք պատվերների բաժինը՝ մանրամասները տեսնելու համար</small>';toast.classList.add('visible');clearTimeout(driverAlertToastTimer);driverAlertToastTimer=setTimeout(()=>toast.classList.remove('visible'),15000);if(driverAlertSoundTimer)clearInterval(driverAlertSoundTimer);playSoftDriverOrderChime();let elapsed=0;driverAlertSoundTimer=setInterval(()=>{elapsed+=1000;if(elapsed>=15000){clearInterval(driverAlertSoundTimer);driverAlertSoundTimer=null;return}playSoftDriverOrderChime()},1000)}
