 root.querySelectorAll('form').forEach(form=>{const scores=[...form.querySelectorAll('[name="score"]')];if(!scores.length)return;form.addEventListener('input',()=>{form.dataset.dirty='true'});form.addEventListener('change',()=>{form.dataset.dirty='true'});const sync=()=>{const score=Number(form.querySelector('[name="score"]:checked')?.value||form.querySelector('select[name="score"]')?.value||5),block=form.querySelector('[data-rating-reasons]');if(block){block.hidden=score>3;block.querySelectorAll('[data-score-reasons]').forEach(group=>{group.hidden=Number(group.dataset.scoreReasons)!==score;group.querySelectorAll('input').forEach(input=>{input.disabled=group.hidden;if(group.hidden)input.checked=false})})}};scores.forEach(input=>input.addEventListener('change',sync));sync()});
 root.querySelectorAll('[data-completion-feedback]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const score=Number(new FormData(form).get('score'));const tags=[...form.querySelectorAll('input[name="tags"]:checked')].map(input=>input.value);const reasonTags=[...form.querySelectorAll('input[name="reasonTags"]:checked')].map(input=>input.value);if(score<=3&&!reasonTags.length){message('#appMessage','Ցածր գնահատականի դեպքում նշեք առնվազն մեկ պատճառ։',true);form.querySelector('[data-rating-reasons]')?.scrollIntoView({behavior:'smooth',block:'center'});return}const comment=form.elements.comment.value.trim();const button=form.querySelector('button[type="submit"]');orderAction(button,'/api/orders/'+form.dataset.completionFeedback+'/complete',{score,tags,reasonTags,comment})});
 root.querySelectorAll('[data-customer-rating]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const score=Number(new FormData(form).get('score'));const reasonTags=[...form.querySelectorAll('input[name="reasonTags"]:checked')].map(input=>input.value);if(score<=3&&!reasonTags.length){message('#appMessage','Ցածր գնահատականի դեպքում նշեք առնվազն մեկ պատճառ։',true);form.querySelector('[data-rating-reasons]')?.scrollIntoView({behavior:'smooth',block:'center'});return}const comment=form.elements.comment.value.trim();orderAction(form.querySelector('button[type="submit"]'),'/api/orders/'+form.dataset.customerRating+'/rate-driver',{score,reasonTags,comment})});
 root.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{if(confirm('Չեղարկե՞լ այս պատվերը։'))orderAction(b,'/api/orders/'+b.dataset.cancel+'/cancel')});
